'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { SubmitIdeaRequestSchema } from '@utmessa/shared';
import type { SubmitIdeaResponse } from '@utmessa/shared';
import FormField from './components/FormField';
import MustHavesList from './components/MustHavesList';
import SubmitButton from './components/SubmitButton';
import SuccessMessage from './components/SuccessMessage';

/**
 * Form data structure
 */
interface FormData {
  title: string;
  problem: string;
  mustHaves: string[];
  email: string;
}

/**
 * Main submission form component
 *
 * Features:
 * - Manages form state (title, problem, mustHaves, email)
 * - Client-side validation with Zod schemas from @utmessa/shared
 * - Submits to POST /api/ideas
 * - Handles loading states and errors
 * - Displays success message and redirects to receipt page
 *
 * @example
 * ```tsx
 * <SubmitForm />
 * ```
 */
export default function SubmitForm() {
  const router = useRouter();

  // Form state
  const [formData, setFormData] = useState<FormData>({
    title: '',
    problem: '',
    mustHaves: [''],
    email: '',
  });

  // Validation errors (keyed by field path)
  const [errors, setErrors] = useState<Record<string, string>>({});

  // Submission state
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [submitSuccess, setSubmitSuccess] = useState(false);
  const [receiptToken, setReceiptToken] = useState<string | null>(null);
  const [apiError, setApiError] = useState<string | null>(null);

  // Auto-redirect after successful submission
  useEffect(() => {
    if (submitSuccess && receiptToken) {
      const timer = setTimeout(() => {
        router.push(`/i/${receiptToken}`);
      }, 3000);
      return () => clearTimeout(timer);
    }
  }, [submitSuccess, receiptToken, router]);

  /**
   * Validate the entire form and return whether it's valid
   */
  const validateForm = (): boolean => {
    // Prepare data for validation (trim strings, filter empty mustHaves)
    const dataToValidate = {
      title: formData.title.trim(),
      problem: formData.problem.trim(),
      mustHaves: formData.mustHaves
        .map((h) => h.trim())
        .filter((h) => h.length > 0),
      email: formData.email.trim() || undefined,
    };

    // Validate with Zod schema
    const result = SubmitIdeaRequestSchema.safeParse(dataToValidate);

    if (!result.success) {
      const newErrors: Record<string, string> = {};
      result.error.errors.forEach((err) => {
        const path = err.path.join('.');
        newErrors[path] = err.message;
      });
      setErrors(newErrors);
      return false;
    }

    setErrors({});
    return true;
  };

  /**
   * Handle form submission
   */
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // Validate form
    if (!validateForm()) {
      return;
    }

    setIsSubmitting(true);
    setApiError(null);

    try {
      // Prepare request data
      const requestData = {
        title: formData.title.trim(),
        problem: formData.problem.trim(),
        mustHaves: formData.mustHaves
          .map((h) => h.trim())
          .filter((h) => h.length > 0),
        email: formData.email.trim() || undefined,
      };

      // Submit to API
      const response = await fetch('/api/ideas', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(requestData),
      });

      // Handle response
      if (!response.ok) {
        if (response.status === 400) {
          const errorData = await response.json();
          setApiError(errorData.error || 'Validation failed. Please check your input.');
        } else if (response.status >= 500) {
          setApiError('Server error. Please try again later.');
        } else {
          setApiError('An unexpected error occurred. Please try again.');
        }
        return;
      }

      // Success
      const data: SubmitIdeaResponse = await response.json();
      setReceiptToken(data.token);
      setSubmitSuccess(true);
    } catch (error) {
      console.error('Submission error:', error);
      setApiError('Network error. Please check your connection and try again.');
    } finally {
      setIsSubmitting(false);
    }
  };

  // Show success message after submission
  if (submitSuccess && receiptToken) {
    return <SuccessMessage token={receiptToken} />;
  }

  return (
    <form
      onSubmit={handleSubmit}
      className="bg-white rounded-2xl shadow-xl p-6 sm:p-8 space-y-6 border border-slate-200"
      noValidate
    >
      {/* Privacy Notice */}
      <div className="bg-amber-50 border-l-4 border-amber-400 p-4 rounded-r">
        <p className="text-sm text-amber-800">
          <strong>Persónuvernd:</strong> Ekki setja inn viðkvæmar, trúnaðar eða
          persónugreinanlegar upplýsingar. Þetta er opinbert kynningarkerfi.
        </p>
      </div>

      {/* Title Field */}
      <FormField
        label="Heiti hugmyndar"
        name="title"
        required
        maxLength={100}
        value={formData.title}
        onChange={(value) => setFormData({ ...formData, title: value })}
        error={errors.title}
        placeholder="t.d. Uppskriftaforrit fyrir fjölskyldur"
        autoFocus
      />

      {/* Problem Field */}
      <FormField
        label="Lýsing á vandamálinu"
        name="problem"
        type="textarea"
        required
        maxLength={500}
        minLength={10}
        value={formData.problem}
        onChange={(value) => setFormData({ ...formData, problem: value })}
        error={errors.problem}
        placeholder="Lýstu vandamálinu sem þú vilt leysa..."
        rows={4}
      />

      {/* Must-Haves List */}
      <MustHavesList
        items={formData.mustHaves}
        onChange={(items) => setFormData({ ...formData, mustHaves: items })}
        errors={errors}
      />

      {/* Email Field */}
      <FormField
        label="Netfang (valfrjálst)"
        name="email"
        type="email"
        value={formData.email}
        onChange={(value) => setFormData({ ...formData, email: value })}
        error={errors.email}
        placeholder="netfang@daemi.is"
        helpText="Fáðu tilkynningu þegar prufuútgáfan er tilbúin"
      />

      {/* API Error */}
      {apiError && (
        <div className="bg-red-50 border-l-4 border-red-400 p-4 rounded-r" role="alert">
          <p className="text-sm text-red-800">{apiError}</p>
        </div>
      )}

      {/* Submit Button */}
      <SubmitButton isSubmitting={isSubmitting} />
    </form>
  );
}

import { NextRequest, NextResponse } from 'next/server';
import { validateOrchKey } from '@/lib/auth/validateOrchKey';
import { deleteIdea, getIdeaById } from '@/lib/db/ideas';
import { z } from 'zod';

/**
 * UUID validation schema
 */
const UUIDSchema = z.string().uuid('Invalid UUID format');

/**
 * DELETE /api/ideas/[id]
 *
 * Delete an idea from the queue. Protected endpoint.
 *
 * Headers:
 * - X-ORCH-KEY: Shared secret for orchestrator authentication (required)
 *
 * URL Parameters:
 * - id: UUID of the idea to delete
 *
 * Response:
 * - 200 OK: Idea successfully deleted
 * - 400 Bad Request: Invalid UUID format
 * - 401 Unauthorized: Invalid or missing X-ORCH-KEY
 * - 404 Not Found: Idea with given ID does not exist
 * - 500 Internal Server Error: Unexpected error
 */
export async function DELETE(
  request: NextRequest,
  { params }: { params: Promise<{ id: string }> }
): Promise<NextResponse> {
  const startTime = performance.now();
  const resolvedParams = await params;
  const ideaId = resolvedParams.id;

  try {
    // 1. Authentication - require X-ORCH-KEY header
    if (!validateOrchKey(request)) {
      console.warn('[API] DELETE /api/ideas/[id]: Authentication failed', { ideaId });
      return NextResponse.json(
        {
          error: 'UNAUTHORIZED',
          message: 'Invalid or missing X-ORCH-KEY header',
        },
        { status: 401 }
      );
    }

    // 2. Validate UUID format
    const uuidResult = UUIDSchema.safeParse(ideaId);
    if (!uuidResult.success) {
      console.warn('[API] DELETE /api/ideas/[id]: Invalid UUID', { ideaId });
      return NextResponse.json(
        {
          error: 'VALIDATION_ERROR',
          message: 'Invalid idea ID format',
          details: [{ field: 'id', message: 'Must be a valid UUID' }],
        },
        { status: 400 }
      );
    }

    // 3. Check if idea exists first (for better error message)
    const existingIdea = await getIdeaById(ideaId);
    if (!existingIdea) {
      console.log('[API] DELETE /api/ideas/[id]: Not found', { ideaId });
      return NextResponse.json(
        {
          error: 'NOT_FOUND',
          message: `Idea with ID ${ideaId} not found`,
        },
        { status: 404 }
      );
    }

    // 4. Delete the idea
    const deleted = await deleteIdea(ideaId);

    if (!deleted) {
      // This shouldn't happen since we checked existence, but handle it anyway
      console.warn('[API] DELETE /api/ideas/[id]: Delete failed unexpectedly', { ideaId });
      return NextResponse.json(
        {
          error: 'NOT_FOUND',
          message: `Idea with ID ${ideaId} not found`,
        },
        { status: 404 }
      );
    }

    // 5. Log success
    const durationMs = performance.now() - startTime;
    console.log('[API] DELETE /api/ideas/[id]: Success', {
      ideaId,
      title: existingIdea.title,
      durationMs: Math.round(durationMs),
    });

    // 6. Return success response
    return NextResponse.json(
      {
        success: true,
        deleted: true,
        id: ideaId,
      },
      { status: 200 }
    );

  } catch (error) {
    // Log full error details server-side
    console.error('[API] DELETE /api/ideas/[id]: Internal error', {
      ideaId,
      error: error instanceof Error ? error.message : 'Unknown error',
      stack: error instanceof Error ? error.stack : undefined,
    });

    // Return safe error message to client
    return NextResponse.json(
      {
        error: 'INTERNAL_ERROR',
        message: 'An unexpected error occurred',
      },
      { status: 500 }
    );
  }
}

