 * Escape HTML special characters to prevent XSS/injection in email templates
 *
 * @param str - The string to escape
 * @returns HTML-safe string
 */
function escapeHtml(str: string): string {
  return str
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
